(2662646, 369132, 46371, '<td valign="top">JUST MAKING MY WAY THRU AND THIS IS PRETTY DAMN GOOD.GREAT SHOT.</td>', 'JUST MAKING MY WAY THRU AND THIS IS PRETTY DAMN GOOD.GREAT SHOT.', '2006-07-26 09:55:59.000000', NULL, 1),
