(2663349, 369084, 62723, '<td valign="top">not sure if the picture would have been more or less effective had you misted the grass surrounding the apples as well. Nice color though!</td>', 'not sure if the picture would have been more or less effective had you misted the grass surrounding the apples as well. Nice color though!', '2006-07-26 12:16:05.000000', NULL, 1),
