INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2663397, 367139, 28617, '<td valign="top">Very colorful but color ON (the same) color? I don''t see it</td>', 'Very colorful but color ON (the same) color? I don''t see it', '2006-07-26 12:25:11.000000', NULL, 1),
(2663415, 367772, 28617, '<td valign="top">Nice shot. Did you try it with a flash? I took a similar shot for the challenge and every time I used the flash, he was not in the picture. He would react to the flash quicker than the picture could be taken and fly off! When I looked at the shot on the camera, no fly, yet there he was on the leaf. It took a number of shots to figure out what was going on.</td>', 'Nice shot. Did you try it with a flash? I took a similar shot for the challenge and every time I used the flash, he was not in the picture. He would react to the flash quicker than the picture could be taken and fly off! When I looked at the shot on the camera, no fly, yet there he was on the leaf. It took a number of shots to figure out what was going on.', '2006-07-26 12:28:48.000000', NULL, 1),
(2663435, 369239, 35947, '<td valign="top">I find the hot spot very distracting.</td>', 'I find the hot spot very distracting.', '2006-07-26 12:33:03.000000', NULL, 1),
(2663447, 367377, 35947, '<td valign="top">With such blue eyes this would work really well with blue too!  Nice job!</td>', 'With such blue eyes this would work really well with blue too!  Nice job!', '2006-07-26 12:35:25.000000', NULL, 1),
(2663448, 369280, 28617, '<td valign="top">I don''t see how this meets the color on (the same) color requirement</td>', 'I don''t see how this meets the color on (the same) color requirement', '2006-07-26 12:35:28.000000', NULL, 1),
(2663455, 369812, 28617, '<td valign="top">the focus seems too soft</td>', 'the focus seems too soft', '2006-07-26 12:36:18.000000', NULL, 1),
(2663463, 367139, 35947, '<td valign="top">AWESOME!  I can''t wait to read your details on how you set this up!  I tried using the color cases for my lines entry but wasn''t happy with the turn out at all.  Backlighting looks key.  Great job!</td>', 'AWESOME!  I can''t wait to read your details on how you set this up!  I tried using the color cases for my lines entry but wasn''t happy with the turn out at all.  Backlighting looks key.  Great job!', '2006-07-26 12:37:52.000000', NULL, 1),
(2663468, 369848, 28617, '<td valign="top">Lots of color but color ON (the same)color? I don''t see it.</td>', 'Lots of color but color ON (the same)color? I don''t see it.', '2006-07-26 12:38:03.000000', NULL, 1),
(2663472, 369345, 28617, '<td valign="top">Almost looks real. Nicely done</td>', 'Almost looks real. Nicely done', '2006-07-26 12:38:39.000000', NULL, 1),
(2663477, 367854, 28617, '<td valign="top">Where is the color ON (the same) color? I don''t see it</td>', 'Where is the color ON (the same) color? I don''t see it', '2006-07-26 12:39:37.000000', NULL, 1),
(2663482, 369781, 61818, '<td valign="top">Pros: those blue eyes really make the shot.  Texture of the paint on the skin really nice.  I like the highlight under the eye.  Like the dof.<br/> <br/>Cons:  The little bit of the other eye that is showing, and the eyebrow, detract from the shot.  Would like to see all of the main eyebrow, and if you had painted or powdered it a lighter shade of blue as well that really would have sex''d it up.  As this was advanced editing, another thing that could really have added some spark would be to either get rid of the veins in the eye or else tint the white part of the eye a light shade of blue as well.<br/> <br/>6.</td>', 'Pros: those blue eyes really make the shot.  Texture of the paint on the skin really nice.  I like the highlight under the eye.  Like the dof. Cons:  The little bit of the other eye that is showing, and the eyebrow, detract from the shot.  Would like to see all of the main eyebrow, and if you had painted or powdered it a lighter shade of blue as well that really would have sex''d it up.  As this was advanced editing, another thing that could really have added some spark would be to either get rid of the veins in the eye or else tint the white part of the eye a light shade of blue as well. 6.', '2006-07-26 12:40:36.000000', NULL, 1),
(2663491, 368790, 61818, '<td valign="top">Really nice.  I like the halo around the orange.  Wish the shadow were a bit darker to provide a bit more contrast.  Also would have liked to see that little bit of green stem plucked out so this would have been purely a composition of oranges.<br/> <br/>6.</td>', 'Really nice.  I like the halo around the orange.  Wish the shadow were a bit darker to provide a bit more contrast.  Also would have liked to see that little bit of green stem plucked out so this would have been purely a composition of oranges. 6.', '2006-07-26 12:41:34.000000', NULL, 1),
(2663493, 368124, 28617, '<td valign="top">Lots of color but where is the color ON (the same) color as required by the challenge?</td>', 'Lots of color but where is the color ON (the same) color as required by the challenge?', '2006-07-26 12:41:48.000000', NULL, 1),
(2663495, 366532, 28617, '<td valign="top">Very nice. I like the green stem leading to the flower</td>', 'Very nice. I like the green stem leading to the flower', '2006-07-26 12:42:16.000000', NULL, 1),
(2663501, 369293, 61818, '<td valign="top">This is a nice shot and a really appealing balance between shades of green.<br/> <br/>With the flat dof, it loses some spark.  I would have liked it if the peas were a bit out of focus, drawing the eye to the leaf.  Or setting the leaf off to one side or the other of the shot.  Any of that or some other method to improve the contrast between subjects would improve the shot, but really nice overall.  <br/> <br/>6.</td>', 'This is a nice shot and a really appealing balance between shades of green. With the flat dof, it loses some spark.  I would have liked it if the peas were a bit out of focus, drawing the eye to the leaf.  Or setting the leaf off to one side or the other of the shot.  Any of that or some other method to improve the contrast between subjects would improve the shot, but really nice overall.   6.', '2006-07-26 12:43:42.000000', NULL, 1),
(2663517, 369447, 61818, '<td valign="top">Ok I''m lowballing this and here is why.  Blue on Blue is what you present as your theme.  Yet the dominant subject in the photo are the large red bars.  Add to this the white railing or knee wall and the brown bit of concrete showing and this is about as far removed from color on color as could be.<br/> <br/>Compositionally, this was a nice idea.  As this is advanced editing, I think you could have taken this and played with the colors to get everything up as shades of blue to better meet the challenge.  Also would have been good to clone out that piece of hair or whatever is in the top right corner.</td>', 'Ok I''m lowballing this and here is why.  Blue on Blue is what you present as your theme.  Yet the dominant subject in the photo are the large red bars.  Add to this the white railing or knee wall and the brown bit of concrete showing and this is about as far removed from color on color as could be. Compositionally, this was a nice idea.  As this is advanced editing, I think you could have taken this and played with the colors to get everything up as shades of blue to better meet the challenge.  Also would have been good to clone out that piece of hair or whatever is in the top right corner.', '2006-07-26 12:46:35.000000', NULL, 1),
(2663529, 369733, 61818, '<td valign="top">This is a good idea and the photo is well taken.  However the cropping off of the top of the leaf and setting the leaf smack in the center of the shot makes this uninteresting.  Moving the leaf off to a side so the contrast between those nice veins and the flat background would really have added some pop to the shot overall.</td>', 'This is a good idea and the photo is well taken.  However the cropping off of the top of the leaf and setting the leaf smack in the center of the shot makes this uninteresting.  Moving the leaf off to a side so the contrast between those nice veins and the flat background would really have added some pop to the shot overall.', '2006-07-26 12:48:17.000000', NULL, 1),
(2663535, 367854, 61818, '<td valign="top">Why even submit this?  This isn''t color on color by any stretch of the imagination.</td>', 'Why even submit this?  This isn''t color on color by any stretch of the imagination.', '2006-07-26 12:48:55.000000', NULL, 1),
(2663538, 368854, 61818, '<td valign="top">If that ugly little bug was more the focus of this shit, perhaps with some lighting on his face, this shot would have been excellent.  The way he is cocking his head really gives life to what is otherwise ''another bug shot''.  A noble attempt! 5.</td>', 'If that ugly little bug was more the focus of this shit, perhaps with some lighting on his face, this shot would have been excellent.  The way he is cocking his head really gives life to what is otherwise ''another bug shot''.  A noble attempt! 5.', '2006-07-26 12:49:56.000000', NULL, 1),
(2663548, 367334, 61818, '<td valign="top">Cropping this so just the shadow on the wall is the shot would have met the challenge and been a pretty decent photo in all regards.  As it is, the orange, brown and black of the bonsai subject detract from the green on green theme and push this towards dnmc.</td>', 'Cropping this so just the shadow on the wall is the shot would have met the challenge and been a pretty decent photo in all regards.  As it is, the orange, brown and black of the bonsai subject detract from the green on green theme and push this towards dnmc.', '2006-07-26 12:52:37.000000', NULL, 1),
(2663560, 369461, 61818, '<td valign="top">Pro''s - water drop shots are always neat, and this play on greens is very appealing<br/> <br/>Con''s - water drop shots are so overdone as to have lost most of their wow factor with the exception of an excellent few - and with hundreds of them littering this site the bar has been raised very high.  The composition would benefit from the drop action being off to one side or the other.  The black reflection underneath is a major distraction.<br/> <br/>A noble attempt.</td>', 'Pro''s - water drop shots are always neat, and this play on greens is very appealing Con''s - water drop shots are so overdone as to have lost most of their wow factor with the exception of an excellent few - and with hundreds of them littering this site the bar has been raised very high.  The composition would benefit from the drop action being off to one side or the other.  The black reflection underneath is a major distraction. A noble attempt.', '2006-07-26 12:54:59.000000', NULL, 1),
(2663563, 367717, 61818, '<td valign="top">Color on color.  Why did you even submit this?</td>', 'Color on color.  Why did you even submit this?', '2006-07-26 12:55:29.000000', NULL, 1),
(2663567, 369280, 61818, '<td valign="top">Well titled. 1.</td>', 'Well titled. 1.', '2006-07-26 12:55:45.000000', NULL, 1),
(2663570, 369302, 61818, '<td valign="top">This is a nice idea.  I don''t care for the weird post processing effect and it is a bummer that the left side got cropped off.  On the upside, excellent attempt at meeting the challenge.  Going to crawl out from under my bridge and actually tack a 6 on to this.</td>', 'This is a nice idea.  I don''t care for the weird post processing effect and it is a bummer that the left side got cropped off.  On the upside, excellent attempt at meeting the challenge.  Going to crawl out from under my bridge and actually tack a 6 on to this.', '2006-07-26 12:57:07.000000', NULL, 1),
(2663577, 367256, 117, '<td valign="top">should have cloned out the time and date.</td>', 'should have cloned out the time and date.', '2006-07-26 12:59:16.000000', NULL, 1),
(2663582, 369345, 61818, '<td valign="top">Very original composition and meets the challenge perfectly.<br/> <br/>Some focus issues going on here, that license plate should be sharp as a tack.  I think yo u overdid the doging around the headlights.  Brush some of the sand off the road on the lower right.  Move car and road to the left of the photo.<br/> <br/>DoF is great on this.<br/> <br/>5.</td>', 'Very original composition and meets the challenge perfectly. Some focus issues going on here, that license plate should be sharp as a tack.  I think yo u overdid the doging around the headlights.  Brush some of the sand off the road on the lower right.  Move car and road to the left of the photo. DoF is great on this. 5.', '2006-07-26 12:59:33.000000', NULL, 1),
(2663584, 368253, 61818, '<td valign="top">Think you focused on the background or something.</td>', 'Think you focused on the background or something.', '2006-07-26 13:00:10.000000', NULL, 1),
(2663591, 368114, 61818, '<td valign="top">Well, hopefully he''s voting and has signed up a bunch of like-minded friends.</td>', 'Well, hopefully he''s voting and has signed up a bunch of like-minded friends.', '2006-07-26 13:01:13.000000', NULL, 1),
(2663593, 367472, 61818, '<td valign="top">Still looks all yellow.  This is a nice photo but the composition is very uninteresting.</td>', 'Still looks all yellow.  This is a nice photo but the composition is very uninteresting.', '2006-07-26 13:02:09.000000', NULL, 1),
(2663597, 368012, 61818, '<td valign="top">Nice shot.  Would have worked better if you let it sink more and not cropped off so close to the top. Personally I like all the bubbles. 5.</td>', 'Nice shot.  Would have worked better if you let it sink more and not cropped off so close to the top. Personally I like all the bubbles. 5.', '2006-07-26 13:03:07.000000', NULL, 1),
(2663603, 369801, 61818, '<td valign="top">Color on Color.  Not ColorS on ColorS.</td>', 'Color on Color.  Not ColorS on ColorS.', '2006-07-26 13:03:50.000000', NULL, 1),
(2663611, 369882, 61818, '<td valign="top">Cut the green stems off the peppers and you''d have really had a winner here.  Shadow on the lower pepper is a bit detracting.  Overall composition is nice. 5.</td>', 'Cut the green stems off the peppers and you''d have really had a winner here.  Shadow on the lower pepper is a bit detracting.  Overall composition is nice. 5.', '2006-07-26 13:04:35.000000', NULL, 1),
(2663616, 369459, 61818, '<td valign="top">Color on Color, not ColorS on ColorS.</td>', 'Color on Color, not ColorS on ColorS.', '2006-07-26 13:05:03.000000', NULL, 1),
(2663628, 369666, 61818, '<td valign="top">Crop out the purple stem or change it''s color to match the other greens and this would have been a great shot.</td>', 'Crop out the purple stem or change it''s color to match the other greens and this would have been a great shot.', '2006-07-26 13:06:12.000000', NULL, 1),
(2663634, 368863, 61818, '<td valign="top">Color on color is the challenge.  Why even submit this?  Blues, whites, greens, yellow, reds.</td>', 'Color on color is the challenge.  Why even submit this?  Blues, whites, greens, yellow, reds.', '2006-07-26 13:06:47.000000', NULL, 1),
(2663639, 369217, 61818, '<td valign="top">Like the shot, but it suffers from the lighting.  Subject needs to jump out from the background more.  A noble attempt. 5.</td>', 'Like the shot, but it suffers from the lighting.  Subject needs to jump out from the background more.  A noble attempt. 5.', '2006-07-26 13:07:41.000000', NULL, 1),
(2663643, 369768, 61818, '<td valign="top">Color on color, not colorS on colorS.</td>', 'Color on color, not colorS on colorS.', '2006-07-26 13:08:24.000000', NULL, 1),
(2663645, 369407, 61818, '<td valign="top">Very nice.  Wish I could see more of the bridge.</td>', 'Very nice.  Wish I could see more of the bridge.', '2006-07-26 13:09:04.000000', NULL, 1),
(2663651, 369814, 61818, '<td valign="top">Would have done better in the BW challenge.  If youa re shooting grays why enter it in a color contest?</td>', 'Would have done better in the BW challenge.  If youa re shooting grays why enter it in a color contest?', '2006-07-26 13:09:54.000000', NULL, 1),
(2663690, 369729, 57772, '<td valign="top">I love the detail of this image.  The different shades of green on the frog are amazing.  one of my favorite images in the challenge.</td>', 'I love the detail of this image.  The different shades of green on the frog are amazing.  one of my favorite images in the challenge.', '2006-07-26 13:21:02.000000', NULL, 1),
(2663704, 369855, 57772, '<td valign="top">I''m glad you chose this background and not a solid color because it makes the shot more interesting to look at. the cactus is lit well but i also like the shadows.</td>', 'I''m glad you chose this background and not a solid color because it makes the shot more interesting to look at. the cactus is lit well but i also like the shadows.', '2006-07-26 13:24:25.000000', NULL, 1),
(2663723, 369132, 57772, '<td valign="top">good work on making the solid colored background more interesting</td>', 'good work on making the solid colored background more interesting', '2006-07-26 13:30:10.000000', NULL, 1),
(2663734, 367139, 57772, '<td valign="top">is it me or does this image look pink floyd-ish?  great idea yet simple! love the colors!</td>', 'is it me or does this image look pink floyd-ish?  great idea yet simple! love the colors!', '2006-07-26 13:32:54.000000', NULL, 1),
(2663752, 369124, 30049, '<td valign="top">This is great!  I love the subject.  You did a good job of positioning.  The textures are wonderful.  Only part you''ll probably get tagged on is the overexposure on the toad''s head.  Best of luck to you.</td>', 'This is great!  I love the subject.  You did a good job of positioning.  The textures are wonderful.  Only part you''ll probably get tagged on is the overexposure on the toad''s head.  Best of luck to you.', '2006-07-26 13:35:02.000000', NULL, 1),
(2663757, 367900, 30049, '<td valign="top">Great eye you have to put this together!  Nice use of material to create a background very suitable to the main subject.  The title helps tie it in also.</td>', 'Great eye you have to put this together!  Nice use of material to create a background very suitable to the main subject.  The title helps tie it in also.', '2006-07-26 13:36:36.000000', NULL, 1),
(2663766, 369829, 61818, '<td valign="top">Absolutely excellent.  So sick of seeing bug shots and then this one comes along that not only meets the challenge to the letter but has excellent lighting, perfect composition, perfect focus.  Damn, the list goes on.  This should be THE STANDARD for bug shots.<br/> <br/>10.  Hope you ribbon.</td>', 'Absolutely excellent.  So sick of seeing bug shots and then this one comes along that not only meets the challenge to the letter but has excellent lighting, perfect composition, perfect focus.  Damn, the list goes on.  This should be THE STANDARD for bug shots. 10.  Hope you ribbon.', '2006-07-26 13:38:06.000000', NULL, 1),
(2663772, 367772, 30049, '<td valign="top">What a very fine slice you''ve taken here.  Too bad you couldn''t get the entire fly (at least the body and farthest wing) in focus - but I know it can be tricky with macro''s like this.  The green on green works well.  Good luck in the challenge.</td>', 'What a very fine slice you''ve taken here.  Too bad you couldn''t get the entire fly (at least the body and farthest wing) in focus - but I know it can be tricky with macro''s like this.  The green on green works well.  Good luck in the challenge.', '2006-07-26 13:38:31.000000', NULL, 1),
(2663783, 366999, 61818, '<td valign="top">Really interesting shot.  Like the facial expression.  PP the eyes red and I think I''d be having nightmares.  8.</td>', 'Really interesting shot.  Like the facial expression.  PP the eyes red and I think I''d be having nightmares.  8.', '2006-07-26 13:40:50.000000', NULL, 1),
