(2664162, 369800, 52549, '<td valign="top">Beautiful. Love the flower too ;-)</td>', 'Beautiful. Love the flower too ;-)', '2006-07-26 15:13:57.000000', NULL, 1),
(2664163, 368915, 58469, '<td valign="top">Texture and light on the eye is very cool.</td>', 'Texture and light on the eye is very cool.', '2006-07-26 15:14:50.000000', NULL, 1),
(2664164, 367823, 52713, '<td valign="top">cool old camera! nice job getting the texures</td>', 'cool old camera! nice job getting the texures', '2006-07-26 15:15:02.000000', NULL, 1),
(2664165, 369670, 52549, '<td valign="top">The brightly lit left hand side is pretty distracting. The rest is beautiful.</td>', 'The brightly lit left hand side is pretty distracting. The rest is beautiful.', '2006-07-26 15:15:11.000000', NULL, 1),
