(2666388, 369822, 39684, '<td valign="top">That''s a very nice color choice. Maybe a bit more centered towards the right would be better (if I had to say anything neg.). Awesome job!</td>', 'That''s a very nice color choice. Maybe a bit more centered towards the right would be better (if I had to say anything neg.). Awesome job!', '2006-07-27 01:11:29.000000', NULL, 1),
(2666395, 369314, 39684, '<td valign="top">I like this one. Simple, yet meets the challenge beautifully. Great work!</td>', 'I like this one. Simple, yet meets the challenge beautifully. Great work!', '2006-07-27 01:13:35.000000', NULL, 1),
