(2666401, 369304, 39684, '<td valign="top">Creative, nice color choice. Good job.</td>', 'Creative, nice color choice. Good job.', '2006-07-27 01:16:12.000000', NULL, 1),
(2666402, 369776, 44996, '<td valign="top">Oh no... Where is the color here? Even if you are pulling the "Black <i>is</i> a color" card. This image is grey on black. Despite that, the image is quality.</td>', 'Oh no... Where is the color here? Even if you are pulling the "Black is a color" card. This image is grey on black. Despite that, the image is quality.', '2006-07-27 01:16:32.000000', NULL, 1),
(2666405, 368854, 39684, '<td valign="top">Neat! A bit more light would have brought the subject out a bit more, other than that, great work! Very sharp!</td>', 'Neat! A bit more light would have brought the subject out a bit more, other than that, great work! Very sharp!', '2006-07-27 01:17:22.000000', NULL, 1),
(2666407, 368012, 39684, '<td valign="top">Really, really cool! Love the shade of green and the bubbles add an intereting texture. Wonderful shot!</td>', 'Really, really cool! Love the shade of green and the bubbles add an intereting texture. Wonderful shot!', '2006-07-27 01:18:29.000000', NULL, 1),
