(2666417, 367472, 39684, '<td valign="top">Very pretty, nice colors and background choice.</td>', 'Very pretty, nice colors and background choice.', '2006-07-27 01:20:59.000000', NULL, 1),
(2666421, 369812, 39684, '<td valign="top">Very cute title. Interesting take on the subject. Great job.</td>', 'Very cute title. Interesting take on the subject. Great job.', '2006-07-27 01:21:53.000000', NULL, 1),
(2666428, 367875, 39684, '<td valign="top">Beautiful subject and nice angle to the left. The rose blends beautifully into the background.</td>', 'Beautiful subject and nice angle to the left. The rose blends beautifully into the background.', '2006-07-27 01:23:18.000000', NULL, 1),
(2666429, 367486, 39702, '<td valign="top">I like the muted colors of the flower and the "raw" textured effect of the flower. Not the usual super sharp, clean, and vibrant DPC fare.  <br/> <br/>The border is somewhat distracting though.</td>', 'I like the muted colors of the flower and the "raw" textured effect of the flower. Not the usual super sharp, clean, and vibrant DPC fare.   The border is somewhat distracting though.', '2006-07-27 01:24:04.000000', NULL, 1),
(2666430, 369717, 39684, '<td valign="top">How cute! Love the angle and subject. Creative!</td>', 'How cute! Love the angle and subject. Creative!', '2006-07-27 01:24:17.000000', NULL, 1),
(2666441, 368457, 62249, '<td valign="top">Wish the mantis head were a little sharper in focus, but it''s still a good shot. The dotted effect on the antenna is cool. Nice blurred foreground</td>', 'Wish the mantis head were a little sharper in focus, but it''s still a good shot. The dotted effect on the antenna is cool. Nice blurred foreground', '2006-07-27 01:27:50.000000', NULL, 1),
(2666445, 369765, 41337, '<td valign="top">Very well done! I did something similar but this is much better at conveying the emotion, IMO. Good luck!</td>', 'Very well done! I did something similar but this is much better at conveying the emotion, IMO. Good luck!', '2006-07-27 01:28:18.000000', NULL, 1),
(2666454, 369304, 39702, '<td valign="top">Great composition, fantastic color. Bump</td>', 'Great composition, fantastic color. Bump', '2006-07-27 01:31:09.000000', NULL, 1),
(2666458, 367486, 62249, '<td valign="top">I don''t care for the border at all. A darker shade of green would have worked better, as would a thinner green line, and eliminate the outer yellow edge. However, I like the photograph itself a lot and like the way you processed it, especially the contrast.</td>', 'I don''t care for the border at all. A darker shade of green would have worked better, as would a thinner green line, and eliminate the outer yellow edge. However, I like the photograph itself a lot and like the way you processed it, especially the contrast.', '2006-07-27 01:32:07.000000', NULL, 1),
(2666462, 369677, 62249, '<td valign="top">You''ve got some very nice shadow effects behind the bowls, especially the lower right one. Highlights on class surface are too hot, though.</td>', 'You''ve got some very nice shadow effects behind the bowls, especially the lower right one. Highlights on class surface are too hot, though.', '2006-07-27 01:34:23.000000', NULL, 1),
(2666464, 369741, 62249, '<td valign="top">Interesting use of bokeh to form your background.</td>', 'Interesting use of bokeh to form your background.', '2006-07-27 01:35:04.000000', NULL, 1),
(2666471, 368905, 62249, '<td valign="top">Like the exposure on the tiles.</td>', 'Like the exposure on the tiles.', '2006-07-27 01:36:40.000000', NULL, 1),
(2666475, 367008, 62249, '<td valign="top">HIghlight on cheek is too bright, but I like the way you let the point of the triangle of light enter the eye.</td>', 'HIghlight on cheek is too bright, but I like the way you let the point of the triangle of light enter the eye.', '2006-07-27 01:37:51.000000', NULL, 1),
(2666477, 369384, 62249, '<td valign="top">Like the touch of blue added by the dragonfly.</td>', 'Like the touch of blue added by the dragonfly.', '2006-07-27 01:38:22.000000', NULL, 1),
(2666479, 367875, 62249, '<td valign="top">The blurred edge just above the uppermost petal, where the edge looks like a repeat of itself, is distracting.</td>', 'The blurred edge just above the uppermost petal, where the edge looks like a repeat of itself, is distracting.', '2006-07-27 01:39:43.000000', NULL, 1),
(2666482, 369633, 62249, '<td valign="top">This has potential. Maybe try it again with a more severe angle of view, such as shifting your camera more to the upper left from where you shot it.</td>', 'This has potential. Maybe try it again with a more severe angle of view, such as shifting your camera more to the upper left from where you shot it.', '2006-07-27 01:41:56.000000', NULL, 1),
(2666484, 366822, 62249, '<td valign="top">Experiment more with the lighting to enhance the shadow areas and not have such a bright white spot on the sphere.</td>', 'Experiment more with the lighting to enhance the shadow areas and not have such a bright white spot on the sphere.', '2006-07-27 01:43:37.000000', NULL, 1),
