(2668152, 368269, 62095, '<td valign="top">A bit too dark for me</td>', 'A bit too dark for me', '2006-07-27 15:18:36.000000', NULL, 1),
(2668161, 369875, 42100, '<td valign="top">Very nice photo!  I like how the eye is drawn to a single raspberry, despite the big mass of them.  Good use of lighting and DOF to get that effect.  The small bokeh circles accent very nicely.</td>', 'Very nice photo!  I like how the eye is drawn to a single raspberry, despite the big mass of them.  Good use of lighting and DOF to get that effect.  The small bokeh circles accent very nicely.', '2006-07-27 15:21:15.000000', NULL, 1),
