(2668286, 369775, 42100, '<td valign="top">The rim lighting on the leaf really make this pop.  Also rather like the composition, with the leaf being place in the lighter portions of the background.  Well done!</td>', 'The rim lighting on the leaf really make this pop.  Also rather like the composition, with the leaf being place in the lighter portions of the background.  Well done!', '2006-07-27 15:52:02.000000', NULL, 1),
(2668293, 369859, 53690, '<td valign="top">That is one knarly looking spider!  His legs match the wood perfectly.  I''m generally not a fan of the subject being so centered, but it works really well in this case (must be the angle and position of the wood).  Very nice.</td>', 'That is one knarly looking spider!  His legs match the wood perfectly.  I''m generally not a fan of the subject being so centered, but it works really well in this case (must be the angle and position of the wood).  Very nice.', '2006-07-27 15:53:05.000000', NULL, 1),
