(2671625, 369007, 30049, '<td valign="top">Simple, yet very nice!  Sometimes I think we all look too hard and miss the simple beauty right in front of us.  ;^)<br/> <br/>I like the bokeh you have on this.  Only nitpick I have is I think you cropped (or composed) too tight on the right.  I know you were going for off-centered or a ROT comp, but it feels like a mistake to lose that last 1/4 inch of spikes.</td>', 'Simple, yet very nice!  Sometimes I think we all look too hard and miss the simple beauty right in front of us.  ;^) I like the bokeh you have on this.  Only nitpick I have is I think you cropped (or composed) too tight on the right.  I know you were going for off-centered or a ROT comp, but it feels like a mistake to lose that last 1/4 inch of spikes.', '2006-07-28 15:02:15.000000', NULL, 1),
(2671629, 369084, 30049, '<td valign="top">Simple, and creative - plus well done.  Good luck.</td>', 'Simple, and creative - plus well done.  Good luck.', '2006-07-28 15:03:37.000000', NULL, 1),
(2671639, 369096, 30049, '<td valign="top">Funny how DOF works sometimes.  ;^)  The rose looks nice and I like the bg used - one minor thing, since this was advanced editing why didn''t you apply a little blur to the bottom right corner and zap those lines in the bg out?</td>', 'Funny how DOF works sometimes.  ;^)  The rose looks nice and I like the bg used - one minor thing, since this was advanced editing why didn''t you apply a little blur to the bottom right corner and zap those lines in the bg out?', '2006-07-28 15:06:11.000000', NULL, 1),
(2671678, 366647, 60799, '<td valign="top">That''s a blue, blue image!  I like it...</td>', 'That''s a blue, blue image!  I like it...', '2006-07-28 15:23:39.000000', NULL, 1),
(2671719, 368151, 60799, '<td valign="top">I really like your idea with this, but for advance editing rules, I think you could have pulled a lot much more color out of the chameleon.  It seems a touch soft along the spikes on his underside and along the top of his head as well.  Overall I''d say nice work though.</td>', 'I really like your idea with this, but for advance editing rules, I think you could have pulled a lot much more color out of the chameleon.  It seems a touch soft along the spikes on his underside and along the top of his head as well.  Overall I''d say nice work though.', '2006-07-28 15:35:06.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2671771, 368926, 60799, '<td valign="top">You''re title gives the image a sad connotation (as it is), but the overall feel of the image seems a little "muted".  I think a heavy hand of dodging and burning could really make this a powerful image.  I am a fan of the colors and the textures though.  9</td>', 'You''re title gives the image a sad connotation (as it is), but the overall feel of the image seems a little "muted".  I think a heavy hand of dodging and burning could really make this a powerful image.  I am a fan of the colors and the textures though.  9', '2006-07-28 15:55:47.000000', NULL, 1),
(2671821, 369304, 61146, '<td valign="top">I LOVE this shot.  The color/texture/contrast is brilliant.</td>', 'I LOVE this shot.  The color/texture/contrast is brilliant.', '2006-07-28 16:15:25.000000', NULL, 1),
