(2684712, 369714, 3351, '<td valign="top">Nice composition, but it looks to me like all you did was tint the entire thing blue.</td>', 'Nice composition, but it looks to me like all you did was tint the entire thing blue.', '2006-08-01 18:48:42.000000', NULL, 1),
(2684714, 369622, 3351, '<td valign="top">Looks dangerous!</td>', 'Looks dangerous!', '2006-08-01 18:48:59.000000', NULL, 1),
