(2685473, 368485, 53147, '<td valign="top">I dont know exactly what it is about this shot but I really really like it. Beautiful colors, cool lines and patterns, an almost odd symmetry and a great perspective. On eof my top picks for this challenge. Bumping up. Back to bump up one more time. Good luck!</td>', 'I dont know exactly what it is about this shot but I really really like it. Beautiful colors, cool lines and patterns, an almost odd symmetry and a great perspective. On eof my top picks for this challenge. Bumping up. Back to bump up one more time. Good luck!', '2006-08-01 22:39:29.000000', NULL, 1),
(2685477, 367120, 53147, '<td valign="top">Nice shot. Love that you can see the water droplets on his teeny tiny body. Nic ecolors and good detail.</td>', 'Nice shot. Love that you can see the water droplets on his teeny tiny body. Nic ecolors and good detail.', '2006-08-01 22:40:26.000000', NULL, 1),
(2685480, 369246, 53147, '<td valign="top">Cant meet the challenge any better than this. Nice shot and bumping up!</td>', 'Cant meet the challenge any better than this. Nice shot and bumping up!', '2006-08-01 22:40:55.000000', NULL, 1),
(2685484, 368114, 53147, '<td valign="top">My favorite of the mantis shots. Well done. Bumping up.</td>', 'My favorite of the mantis shots. Well done. Bumping up.', '2006-08-01 22:41:38.000000', NULL, 1),
(2685490, 367111, 53147, '<td valign="top">Nice simple shot. Great colors and detail on the frog. I like the angle you have on the leaf as well. Bumping up.</td>', 'Nice simple shot. Great colors and detail on the frog. I like the angle you have on the leaf as well. Bumping up.', '2006-08-01 22:42:26.000000', NULL, 1),
(2685493, 366647, 53147, '<td valign="top">Coming back and looking at this again I like it even better. A great different shot amongst the other entries and the colors are quite pleasing. Bumping up.</td>', 'Coming back and looking at this again I like it even better. A great different shot amongst the other entries and the colors are quite pleasing. Bumping up.', '2006-08-01 22:43:21.000000', NULL, 1),
